CREATE INDEX idx_availability_watch_last_checked ON availability_watch (last_checked_at);

CREATE INDEX idx_discover_sliders_sort_order ON discover_sliders (sort_order);

CREATE INDEX idx_grabs_download_gid ON grabs (download_gid);

CREATE UNIQUE INDEX idx_grabs_held_request ON grabs (mode, tmdb_id) WHERE hold_until != '';

CREATE INDEX idx_grabs_mode_status ON grabs (mode, status);

CREATE INDEX idx_library_episodes_series ON library_episodes (series_id);

CREATE INDEX idx_library_items_collection_id ON library_items(collection_id);

CREATE INDEX idx_library_items_mode ON library_items (mode);

CREATE INDEX idx_library_scenes_box_scene ON library_scenes (box, scene_id);

CREATE INDEX idx_library_series_tmdb ON library_series (tmdb_id);

CREATE INDEX idx_proposals_mode_workflow_status ON proposals (mode, workflow, status);

CREATE INDEX idx_pruning_rules_mode ON pruning_rules (mode, enabled);

CREATE UNIQUE INDEX idx_purge_allowlist_mode_tag ON purge_allowlist (mode, lower(tag));

CREATE INDEX idx_rss_feeds_sort_order ON rss_feeds (sort_order);

CREATE INDEX idx_service_connections_kind ON service_connections (kind, enabled);

CREATE INDEX idx_stashbox_databases_priority ON stashbox_databases (enabled, priority);

CREATE UNIQUE INDEX parse_performers_norm ON parse_performers (name_norm);

CREATE UNIQUE INDEX parse_studios_norm ON parse_studios (name_norm);

CREATE UNIQUE INDEX IF NOT EXISTS library_tags_tag_lower_uidx ON library_tags (item_id, lower(tag));

CREATE UNIQUE INDEX IF NOT EXISTS library_series_tags_tag_lower_uidx ON library_series_tags (series_id, lower(tag));

CREATE UNIQUE INDEX IF NOT EXISTS library_scene_tags_tag_lower_uidx ON library_scene_tags (scene_id, lower(tag));

